mapper.select:
SELECT point_balance
FROM users
WHERE user_id = #{userId}

mapper.update:
UPDATE users
SET point_balance = point_balance - #{amount},
    updated_at = #{updatedAt}
WHERE user_id = #{userId}
  AND point_balance >= #{amount}

