INSERT INTO point_transactions (
    user_id, transaction_type, amount, reason_type, reason_id,
    balance_after, idempotency_key, occurred_at, created_at
) VALUES (
    #{userId}, #{transactionType}, #{amount}, #{reasonType},
    #{reasonId,jdbcType=BIGINT}, #{balanceAfter}, #{idempotencyKey},
    #{occurredAt}, #{createdAt}
)

mapper.update:
UPDATE point_transactions
SET reason_id = #{gifticonOrderId}
WHERE point_transaction_id = #{pointTransactionId}
  AND reason_type = 'GIFTICON'
  AND reason_id IS NULL

mapper.insert:
INSERT INTO gifticon_orders (
    user_id, gifticon_product_id, gifticon_code_id,
    point_transaction_id, spent_points, product_snapshot_json,
    idempotency_key, request_fingerprint, first_disclosed_at, completed_at
) VALUES (
    #{userId}, #{gifticonProductId}, #{gifticonCodeId},
    #{pointTransactionId}, #{spentPoints}, #{productSnapshotJson},
    #{idempotencyKey}, #{requestFingerprint},
    #{firstDisclosedAt,jdbcType=TIMESTAMP}, #{completedAt}
)

mapper.select:
SELECT 
FROM gifticon_orders o
JOIN point_transactions pt
  ON pt.point_transaction_id = o.point_transaction_id
JOIN gifticon_codes c
  ON c.gifticon_code_id = o.gifticon_code_id
WHERE o.user_id = #{userId}
AND o.gifticon_order_id < #{cursor}
ORDER BY o.gifticon_order_id DESC
LIMIT #{size}

mapper.update:
UPDATE gifticon_orders
SET first_disclosed_at = #{disclosedAt}
WHERE gifticon_order_id = #{gifticonOrderId}
  AND first_disclosed_at IS NULL

